--
-- Table structure for table `wf_event_action_config`
--

DROP TABLE IF EXISTS `wf_event_action_config`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `wf_event_action_config` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户ID（0=全局）',
  `biz_type` varchar(64) NOT NULL COMMENT '业务类型，如 EXP_CLAIM / PURCHASE_ORDER_REVIEW',
  `action_bean` varchar(128) NOT NULL COMMENT 'Spring Bean 名称（实现 WfBizAction 接口）',
  `trigger_when` varchar(16) NOT NULL DEFAULT 'BOTH' COMMENT '触发时机：APPROVED 仅通过 / REJECTED 仅驳回 / BOTH 两者均触发',
  `sort_order` int NOT NULL DEFAULT '0' COMMENT '同一 bizType 内执行顺序（升序）',
  `enabled` tinyint NOT NULL DEFAULT '1' COMMENT '是否启用：1=是 0=否',
  `description` varchar(256) DEFAULT NULL COMMENT '描述',
  `create_by` bigint DEFAULT NULL,
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `update_by` bigint DEFAULT NULL,
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `del_flag` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_biz_bean_trigger` (`tenant_id`,`biz_type`,`action_bean`,`trigger_when`),
  KEY `idx_biz_type` (`biz_type`,`enabled`)
) ENGINE=InnoDB AUTO_INCREMENT=75 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='流程事件收尾动作配置（表驱动，事件编排总线）';
/*!40101 SET character_set_client = @saved_cs_client */;

